using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using NexaBook.Api.Data;
namespace NexaBook.Api.Controllers;[ApiController,Route("api/notifications"),Authorize]public class NotificationsController(AppDbContext db):ControllerBase{[HttpGet]public async Task<IActionResult>Get(){var id=int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);return Ok(await db.Notifications.Where(x=>x.UserId==id).OrderByDescending(x=>x.CreatedAt).Take(50).ToListAsync());}[HttpPut("{id}/read")]public async Task<IActionResult>Read(int id){var n=await db.Notifications.FindAsync(id);if(n is null)return NotFound();n.IsRead=true;await db.SaveChangesAsync();return NoContent();}}
